answers.workaround:
I tried! I tried to write an editor export plugin that parses the raw `export_presets.cfg` file and auto-increments the version code on every export, but it turns out that export preset properties are cached and the `export_presets.cfg` file gets overwritten when an export is done, so... I couldn't figure out a way.

<details>

<summary>For reference, here's the code in my EditorExportPlugin that could not what this proposal proposes.</summary>

```
_set_value_in_all_config_options_sections("Android", "version/code", version_code + 1)


func _set_value_in_all_config_options_sections(preset_name_contains: String, option_id: String, option_val: Variant) -> void:
	var config: ConfigFile = ConfigFile.new()
	config.load("res://export_presets.cfg")
	for options_section: String in _get_options_section(config, preset_name_contains):
		print("setting ", option_id, " to ", option_val, " in ", preset_name_contains)
		config.set_value(options_section, option_id, option_val)
	config.save("res://export_presets.cfg")


func _get_options_section(config: ConfigFile, contained_name: String) -> Array[String]:
	var a: Array[String] = []
	for section: String in config.get_sections():
		if config.has_section_key(section, "name"):
			var section_name: String = config.get_value(section, "name") as String
			if not section_name.contains(contained_name):
				continue
			a.append(section + ".options")
	return a
```

